"use client";

import { useState } from "react";
import { saveSurveilansMassal } from "@/services/surveilans";

type StateRow = {
  nama_pasien: string;
  no_rm: string;
  uc: number;
  cvl: number;
  ivl: number;
  ett: number;
  vap: number;
  hap: number;
  isk: number;
  iad: number;
  tirah_baring: number;
  plebitis: number;
  hasil_kultur: string;
  antibiotik: string;
};

export default function FormHarian() {
  const [loading, setLoading] = useState(false);
  const [tanggal, setTanggal] = useState("");

  const rowTemplate: StateRow = {
    nama_pasien: "", no_rm: "",
    uc: 0, cvl: 0, ivl: 0, ett: 0,
    vap: 0, hap: 0, isk: 0, iad: 0,
    tirah_baring: 0, plebitis: 0,
    hasil_kultur: "", antibiotik: "",
  };

  const [rows, setRows] = useState<StateRow[]>([{ ...rowTemplate }]);

  const addRow = () => setRows([...rows, { ...rowTemplate }]);
  const removeRow = (index: number) => {
    if (rows.length > 1) setRows(rows.filter((_, i) => i !== index));
  };

  const updateRow = (index: number, field: keyof StateRow, value: any) => {
    const updatedRows = [...rows];
    updatedRows[index] = { ...updatedRows[index], [field]: value };
    setRows(updatedRows);
  };

  const handleSave = async () => {
    if (!tanggal) return alert("Silakan pilih tanggal terlebih dahulu!");
    const validRows = rows.filter((r) => r.nama_pasien.trim() !== "");
    if (validRows.length === 0) return alert("Isi minimal satu nama pasien!");

    setLoading(true);
    try {
      const dataToSave = validRows.map((r) => ({ ...r, tanggal }));
      const result = await saveSurveilansMassal(dataToSave);
      if (result.success) {
        alert("Data Surveilans RS Arun Lhokseumawe Berhasil Disimpan!");
        setRows([{ ...rowTemplate }]);
      }
    } catch (err: any) {
      alert("Gagal menyimpan data: " + err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-slate-200 w-fit">
        <label className="font-bold text-slate-700 text-sm">📅 TANGGAL PEMANTAUAN:</label>
        <input type="date" value={tanggal} className="border border-slate-300 p-2 rounded-lg outline-none text-sm" onChange={(e) => setTanggal(e.target.value)} />
      </div>

      <div className="overflow-x-auto rounded-xl border border-slate-200 shadow-xl bg-white">
        <table className="min-w-full border-collapse text-[10px]">
          <thead className="bg-slate-100 text-slate-700 font-bold uppercase tracking-wider">
            <tr>
              <th rowSpan={2} className="border p-2 min-w-[120px]">Nama Pasien</th>
              <th rowSpan={2} className="border p-2 min-w-[70px]">RM</th>
              <th colSpan={4} className="border p-1 bg-pink-50 text-pink-700 text-center">Tindakan</th>
              <th colSpan={4} className="border p-1 bg-blue-50 text-blue-700 text-center">Infeksi (HAIs)</th>
              <th colSpan={2} className="border p-1 bg-yellow-50 text-yellow-700 text-center">Lainnya</th>
              <th rowSpan={2} className="border p-2 min-w-[100px]">Hasil Kultur</th>
              <th rowSpan={2} className="border p-2 min-w-[100px]">Antibiotik</th>
              <th rowSpan={2} className="border p-2 w-[40px]">X</th>
            </tr>
            <tr className="bg-slate-50">
              <th className="border p-1 text-center">UC</th><th className="border p-1 text-center">CVL</th>
              <th className="border p-1 text-center">IVL</th><th className="border p-1 text-center">ETT</th>
              <th className="border p-1 text-center">VAP</th><th className="border p-1 text-center">HAP</th>
              <th className="border p-1 text-center">ISK</th><th className="border p-1 text-center">IAD</th>
              <th className="border p-1 text-center">TB</th><th className="border p-1 text-center">PLB</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row, idx) => (
              <tr key={idx} className="hover:bg-slate-50">
                <td className="border p-1"><input className="w-full" value={row.nama_pasien} onChange={e => updateRow(idx, 'nama_pasien', e.target.value)} /></td>
                <td className="border p-1"><input className="w-full text-center" value={row.no_rm} onChange={e => updateRow(idx, 'no_rm', e.target.value)} /></td>
                {['uc', 'cvl', 'ivl', 'ett', 'vap', 'hap', 'isk', 'iad', 'tirah_baring', 'plebitis'].map((col) => (
                  <td key={col} className="border p-1 text-center">
                    <input type="checkbox" checked={row[col as keyof StateRow] === 1} onChange={e => updateRow(idx, col as keyof StateRow, e.target.checked ? 1 : 0)} />
                  </td>
                ))}
                <td className="border p-1"><input className="w-full" value={row.hasil_kultur} onChange={e => updateRow(idx, 'hasil_kultur', e.target.value)} /></td>
                <td className="border p-1"><input className="w-full" value={row.antibiotik} onChange={e => updateRow(idx, 'antibiotik', e.target.value)} /></td>
                <td className="border p-1 text-center"><button onClick={() => removeRow(idx)} className="text-red-500 font-bold">×</button></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="flex justify-between items-center p-4 bg-slate-50 rounded-xl border border-dashed border-slate-300">
        <button onClick={addRow} className="bg-emerald-600 text-white px-4 py-2 rounded-lg font-bold shadow-sm">+ Pasien</button>
        <button onClick={handleSave} disabled={loading} className="bg-blue-600 text-white px-8 py-2 rounded-lg font-extrabold shadow-md disabled:bg-slate-400">
          {loading ? "Menyimpan..." : "SIMPAN KE DATABASE"}
        </button>
      </div>
    </div>
  );
}